import{_ as e,o as s,c as t,a0 as a}from"./chunks/framework.B6reNh8h.js";const c=JSON.parse('{"title":"Wire ops","description":"","frontmatter":{},"headers":[],"relativePath":"reference/wire-ops.md","filePath":"reference/wire-ops.md"}'),o={name:"reference/wire-ops.md"};function d(n,i,h,r,l,p){return s(),t("div",null,[...i[0]||(i[0]=[a('<h1 id="wire-ops" tabindex="-1">Wire ops <a class="header-anchor" href="#wire-ops" aria-label="Permalink to &quot;Wire ops&quot;">​</a></h1><p>The ndjson JSON-RPC convention every pavo driver speaks on its <code>serve</code> verb — the same framing as <code>tamias-serve</code>, <code>myco serve</code>, <code>cuora serve</code>, <code>sepia serve</code>. One JSON object per line on stdin, one response per line on stdout.</p><p>Rust source of truth: <code>crates/pavo-protocol/src/wire.rs</code>; <code>protocol/v1/wire.schema.json</code> mirrors it.</p><h2 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to &quot;Envelope&quot;">​</a></h2><p>Requests are discriminated by <code>op</code> (internally tagged, lowercase):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manifest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;views&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;view&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;view&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;board&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;open&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;items&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;render&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;graph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">…</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">…</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;surface&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cli&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;format&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;svg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;submit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;view&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;form&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;set-config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;values&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myco.theme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dark&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Responses:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">…</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Fields for the non-matching arm are absent (not null) — consumers match on <code>ok</code> alone. A driver must never crash the wire: malformed input and serialization failures become <code>ok:false</code> responses.</p><h2 id="ops" tabindex="-1">Ops <a class="header-anchor" href="#ops" aria-label="Permalink to &quot;Ops&quot;">​</a></h2><h3 id="manifest" tabindex="-1"><code>manifest</code> <a class="header-anchor" href="#manifest" aria-label="Permalink to &quot;`manifest`&quot;">​</a></h3><p><code>{&quot;op&quot;:&quot;manifest&quot;}</code> → <a href="/pavo/reference/driver-manifest.html"><code>DriverManifest</code></a>. Discovery verb — cheap, must not require product state. This is how pavo decides a <code>tamias-driver-*</code> is a view driver (<code>&quot;serve&quot;</code> in <code>verbs</code> or <code>&quot;pavo&quot;</code> in <code>capabilities</code>).</p><h3 id="views" tabindex="-1"><code>views</code> <a class="header-anchor" href="#views" aria-label="Permalink to &quot;`views`&quot;">​</a></h3><p><code>{&quot;op&quot;:&quot;views&quot;}</code> → <code>Vec&lt;ViewSummary&gt;</code> — <code>{id, title, route, description?, queries[]}</code> per view, without the <code>root</code> trees. Lightweight listing for <code>pavo views</code> and picker UIs; full trees come from <code>view</code>.</p><h3 id="view" tabindex="-1"><code>view</code> <a class="header-anchor" href="#view" aria-label="Permalink to &quot;`view`&quot;">​</a></h3><p><code>{&quot;op&quot;:&quot;view&quot;,&quot;view&quot;:&quot;&lt;id&gt;&quot;,&quot;params&quot;:{…}}</code> → <a href="/pavo/reference/wire-ops.html#viewresult"><code>ViewResult</code></a>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;view&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">…ViewSpec</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> including</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> root</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> tree…</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;&lt;binding-name&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&lt;payload&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">…</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>The host resolves each <code>QueryBinding</code> on the spec (calling its <code>op</code> with static params merged under caller <code>params</code>) and puts results in <code>data</code> keyed by binding name — <code>data[&quot;items&quot;]</code> feeds every node whose <code>query == &quot;items&quot;</code>. <strong>Partial degradation</strong>: a binding that fails appears as <code>{&quot;error&quot;: &quot;…&quot;}</code> in <code>data</code> rather than failing the whole view.</p><h3 id="query" tabindex="-1"><code>query</code> <a class="header-anchor" href="#query" aria-label="Permalink to &quot;`query`&quot;">​</a></h3><p><code>{&quot;op&quot;:&quot;query&quot;,&quot;query&quot;:&quot;&lt;name&gt;&quot;,&quot;params&quot;:{…}}</code> → <code>{&quot;query&quot;:&quot;&lt;name&gt;&quot;,&quot;data&quot;:&lt;payload&gt;}</code> — execute a single named query binding, or a raw product op for thin drivers. Powers <code>pavo query</code> and ad-hoc data probes; also the transport the <a href="/pavo/how-to/use-config-api.html">config API</a> rides (<code>query</code> = <code>get</code>/<code>set</code>/ <code>resolve</code>/<code>sources</code>/<code>config</code>).</p><h3 id="render" tabindex="-1"><code>render</code> <a class="header-anchor" href="#render" aria-label="Permalink to &quot;`render`&quot;">​</a></h3><p><code>{&quot;op&quot;:&quot;render&quot;,&quot;kind&quot;:&quot;&lt;kind&gt;&quot;,&quot;node&quot;:{…ViewNode verbatim…}, &quot;data&quot;:{…view data map…},&quot;surface&quot;:&quot;cli|tui|web&quot;,&quot;format&quot;:&quot;…&quot;?}</code> → <a href="/pavo/reference/wire-ops.html#rendermodel"><code>RenderModel</code></a> — the renderer-plugin verb. Only sent to drivers whose manifest claims the node&#39;s kind on the asking surface (see <a href="/pavo/explanation/renderer-plugins.html">Renderer plugins</a>).</p><ul><li><code>node</code> — raw ViewNode JSON, passed untyped so unknown/future fields survive.</li><li><code>data</code> — the same binding map <code>view</code> results carry.</li><li><code>surface</code> — open string; hosts may add surfaces.</li><li><code>format</code> — the surface&#39;s format hint when one applies.</li></ul><h3 id="submit" tabindex="-1"><code>submit</code> <a class="header-anchor" href="#submit" aria-label="Permalink to &quot;`submit`&quot;">​</a></h3><p><code>{&quot;op&quot;:&quot;submit&quot;,&quot;view&quot;:&quot;&lt;id&gt;&quot;,&quot;form&quot;:&quot;&lt;id&gt;&quot;?,&quot;values&quot;:{…}}</code> → <a href="#submitresult"><code>SubmitResult</code></a> — the form-submission verb. A surface collects the editable fields of a <code>form</code> ViewNode and posts their <code>key</code> → value pairs here.</p><ul><li><code>view</code> — the view the form lives in (same namespace as <code>view</code>).</li><li><code>form</code> — optional form-node <code>id</code> when the view carries several forms; absent = the driver&#39;s default/first form.</li><li><code>values</code> — submitted field values keyed by <code>FormField.key</code>.</li></ul><p>The driver resolves the form node, reads its <code>submit_op</code> (driver-defined: <code>&quot;set&quot;</code>, <code>&quot;update&quot;</code>, <code>&quot;add&quot;</code>, …), and answers a <code>SubmitResult</code>. Drivers without form support answer <code>ok:false</code>. <code>pavo submit &lt;driver&gt;:&lt;view&gt; --param k=v …</code> is the CLI face; <code>GET /api/submit?ref=…&amp;values={…}</code> the web-bridge face.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><h3 id="viewsummary" tabindex="-1">ViewSummary <a class="header-anchor" href="#viewsummary" aria-label="Permalink to &quot;ViewSummary&quot;">​</a></h3><p><code>{id, title, route, description?, queries[]}</code> — a <code>ViewSpec</code> minus <code>root</code>, for cheap listing.</p><h3 id="viewresult" tabindex="-1">ViewResult <a class="header-anchor" href="#viewresult" aria-label="Permalink to &quot;ViewResult&quot;">​</a></h3><p><code>{view: ViewSpec, data: {&lt;binding&gt;: payload}}</code> — the resolved view. Failed bindings carry <code>{&quot;error&quot;: &quot;…&quot;}</code> payloads.</p><h3 id="queryresult" tabindex="-1">QueryResult <a class="header-anchor" href="#queryresult" aria-label="Permalink to &quot;QueryResult&quot;">​</a></h3><p><code>{query: string, data: any}</code> — one binding&#39;s data payload; shape is driver-defined, hosts pass it through verbatim.</p><h3 id="submitresult" tabindex="-1">SubmitResult <a class="header-anchor" href="#submitresult" aria-label="Permalink to &quot;SubmitResult&quot;">​</a></h3><p><code>{message?, errors?, data?, view?}</code> — every field optional; a bare <code>{&quot;message&quot;:&quot;…&quot;}</code> is complete. <code>errors</code> is a per-field validation map keyed by <code>FormField.key</code> — non-empty means the driver <em>rejected</em> the submit (hosts re-render with the messages; <code>pavo submit</code> exits 1). <code>view</code>, when present, is a fresh <code>ViewResult</code> to swap in. Unknown fields survive typed round-trips.</p><h3 id="rendermodel" tabindex="-1">RenderModel <a class="header-anchor" href="#rendermodel" aria-label="Permalink to &quot;RenderModel&quot;">​</a></h3><p>The canonical intermediate output a renderer plugin emits — internally tagged on <code>&quot;type&quot;</code>:</p><table tabindex="0"><thead><tr><th><code>type</code></th><th>shape</th><th>CLI</th><th>TUI</th><th>web</th></tr></thead><tbody><tr><td><code>rows</code></td><td><code>{type, headers[], aligns?[], rows[][]}</code></td><td>aligned table</td><td>table rows</td><td><code>&lt;table&gt;</code></td></tr><tr><td><code>svg</code></td><td><code>{type, markup}</code> — self-contained <code>&lt;svg&gt;</code></td><td>raw markup</td><td><code>[svg]</code> hint</td><td><code>v-html</code> island</td></tr><tr><td><code>text</code></td><td><code>{type, lines[]}</code></td><td>lines</td><td>lines</td><td><code>&lt;pre&gt;</code></td></tr><tr><td><code>placeholder</code></td><td><code>{type, component, props?}</code></td><td><code>[component]</code></td><td>box + detail</td><td>named component</td></tr></tbody></table><p>Rules: no HTML in RenderModel (self-contained markup is <code>svg</code> only); unknown <code>type</code> degrades like <code>placeholder</code>; plugins needing richer output use <code>placeholder</code> or <code>svg</code>.</p><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p><strong>Additive-only within v1</strong>: new optional fields, new <code>op</code>s, new <code>kind</code>/<code>type</code> variants may appear at any time; existing fields and spellings never change meaning. Unknown ops are protocol errors — hosts surface the driver&#39;s raw error text. Breaking changes bump the version directory (<code>protocol/v2/</code>) with a migration note; v1 stays frozen for existing drivers.</p>',42)])])}const u=e(o,[["render",d]]);export{c as __pageData,u as default};
